// --- APP STATE ---
let currentLang = 'sr';
let currentCategory = 'main';

// --- INITIALIZATION ---
document.addEventListener('DOMContentLoaded', () => {
  document.getElementById('currentYear').textContent = new Date().getFullYear();
  initLanguageSwitcher();
  initMobileNav();
  renderMenuCategories();
  renderMenuItems();
  renderReviews();
});

// --- LANGUAGE SWITCHER ---
function initLanguageSwitcher() {
  const langButtons = document.querySelectorAll('.lang-btn');
  langButtons.forEach(btn => {
    btn.addEventListener('click', (e) => {
      const lang = e.target.getAttribute('data-lang');
      if (lang && lang !== currentLang) {
        setLanguage(lang);
      }
    });
  });
}

function setLanguage(lang) {
  currentLang = lang;
  
  // Update button states
  document.querySelectorAll('.lang-btn').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-lang') === lang);
  });

  // Update HTML lang attribute
  document.documentElement.lang = lang;

  // Update DOM text elements
  const elements = document.querySelectorAll('[data-i18n]');
  elements.forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (translations[lang] && translations[lang][key]) {
      el.textContent = translations[lang][key];
    }
  });

  // Re-render Dynamic Menu & Reviews
  renderMenuCategories();
  renderMenuItems();
  renderReviews();
}

// --- MOBILE NAVIGATION ---
function initMobileNav() {
  const toggle = document.getElementById('mobileToggle');
  const nav = document.getElementById('navMenu');
  
  if (toggle && nav) {
    toggle.addEventListener('click', () => {
      nav.classList.toggle('active');
    });

    // Close on nav link click
    nav.querySelectorAll('.nav-link').forEach(link => {
      link.addEventListener('click', () => {
        nav.classList.remove('active');
      });
    });
  }
}

// --- MENU RENDER LOGIC ---
function renderMenuCategories() {
  const catContainer = document.getElementById('menuCategories');
  if (!catContainer) return;

  const categories = menuCategoriesData[currentLang] || menuCategoriesData.sr;
  
  catContainer.innerHTML = categories.map(cat => `
    <button class="menu-cat-btn ${cat.id === currentCategory ? 'active' : ''}" data-cat="${cat.id}">
      ${cat.label}
    </button>
  `).join('');

  // Add click listeners
  catContainer.querySelectorAll('.menu-cat-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      currentCategory = e.currentTarget.getAttribute('data-cat');
      
      catContainer.querySelectorAll('.menu-cat-btn').forEach(b => b.classList.remove('active'));
      e.currentTarget.classList.add('active');
      
      renderMenuItems();
    });
  });
}

function renderMenuItems() {
  const menuContent = document.getElementById('menuContent');
  if (!menuContent) return;

  const items = (menuItemsData[currentLang] && menuItemsData[currentLang][currentCategory]) 
    ? menuItemsData[currentLang][currentCategory] 
    : [];

  if (items.length === 0) {
    menuContent.innerHTML = '<p class="text-center">Nema stavki u ovoj kategoriji.</p>';
    return;
  }

  menuContent.innerHTML = items.map(item => `
    <div class="menu-item-card">
      <div class="menu-item-info">
        <h3 class="menu-item-title">${item.name}</h3>
        <p class="menu-item-desc">${item.desc}</p>
      </div>
      <div class="menu-item-price">${item.price}</div>
    </div>
  `).join('');
}

// --- REVIEWS RENDER LOGIC ---
function renderReviews() {
  const reviewsContainer = document.getElementById('reviewsSlider');
  if (!reviewsContainer) return;

  const reviews = reviewsData[currentLang] || reviewsData.sr;

  reviewsContainer.innerHTML = reviews.map(rev => `
    <div class="review-card">
      <p class="review-text">"${rev.text}"</p>
      <div class="review-author">
        <span class="author-name">${rev.author}</span>
        <div class="stars">★★★★★</div>
      </div>
    </div>
  `).join('');
}